INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Netzwerkadresse immer die erste Adresse im Subnetz?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert den Subnetzstart"}, {"text": "Nein", "correct": false, "because": "Korrekte Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadresse hat 192.168.1.32 mit /27?', 3, '[{"text": "192.168.1.32", "correct": true, "because": "Inkrement 32, erste Adresse"}, {"text": "192.168.1.0", "correct": false, "because": "Für /24"}, {"text": "192.168.1.64", "correct": false, "because": "Nächstes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Netzwerkadresse hat alle Hostbits auf 0. b) Sie ist immer 0.0.0.0.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nur bei /0"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Netzwerkadresse?', 4, '[{"text": "Hostbits", "correct": false, "because": "Müssen 0 sein"}, {"text": "Inkrement", "correct": false, "because": "Bestimmt Subnetzstart"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 10.0.0.0 die Netzwerkadresse von /8 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Erste Adresse im Bereich"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadresse hat 172.16.1.0 mit /26?', 3, '[{"text": "172.16.1.0", "correct": true, "because": "Inkrement 64, erste Adresse"}, {"text": "172.16.0.0", "correct": false, "because": "Für /16"}, {"text": "172.16.1.64", "correct": false, "because": "Nächstes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die Netzwerkadresse?', 5, '[{"text": "Erste Adresse", "correct": true, "because": "Startet Subnetz"}, {"text": "Hostbits auf 0", "correct": true, "because": "Definiert Netz"}, {"text": "Letzte Adresse", "correct": false, "because": "Das ist Broadcast"}, {"text": "Zufällige Bits", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Netzwerkadresse ist nicht nutzbar. b) Sie hat Hostbits auf 1. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) Hostbits sind 0"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Netzwerkadresse?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Hostbits"}, {"text": "Inkrement", "correct": false, "because": "Bestimmt Grenzen"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 192.168.1.0 die Netzwerkadresse von /25?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 128, erste Adresse"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadresse hat 10.0.0.128 mit /25?', 4, '[{"text": "10.0.0.128", "correct": true, "because": "Inkrement 128, zweite Subnetz"}, {"text": "10.0.0.0", "correct": false, "because": "Erstes Subnetz"}, {"text": "10.0.0.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Netzwerkadresse auch ein Host sein kann. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Reserviert für Netz"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Netzwerkadresse?', 3, '[{"text": "Inkrement", "correct": true, "because": "Bestimmt Subnetzstart"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 172.16.0.0 ist /16-Netzwerkadresse. b) Sie ist immer die höchste Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Broadcast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadressen passen zu /26?', 5, '[{"text": "192.168.1.0", "correct": true, "because": "Inkrement 64"}, {"text": "192.168.1.64", "correct": true, "because": "Zweites Subnetz"}, {"text": "192.168.1.127", "correct": false, "because": "Broadcast"}, {"text": "192.168.1.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Netzwerkadresse unwichtig?', 3, '[{"text": "Hostbits", "correct": false, "because": "Müssen 0 sein"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Grenze"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 10.0.0.64 die Netzwerkadresse bei /26?', 3, '[{"text": "Ja", "correct": true, "because": "Inkrement 64, zweite Subnetz"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.128 /25-Netzwerkadresse ist?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 128, zweite Subnetz"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadresse hat 172.16.2.0 mit /23?', 4, '[{"text": "172.16.2.0", "correct": true, "because": "Inkrement 512, zweite Subnetz"}, {"text": "172.16.0.0", "correct": false, "because": "Erstes Subnetz"}, {"text": "172.16.3.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist die Netzwerkadresse von 192.168.1.96 /28?', 3, '[{"text": "192.168.1.96", "correct": true, "because": "Inkrement 16, siebte Subnetz"}, {"text": "192.168.1.0", "correct": false, "because": "Für /24"}, {"text": "192.168.1.112", "correct": false, "because": "Nächstes Subnetz"}]');
